-- IPA FY2023 SG public questions (15 questions).
-- Official question paper and answer key:
-- https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf
-- https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_ans.pdf
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2023-01','exam-sg','情報セキュリティ管理基準','standard','single_choice','【2023年度 IPA公開問題 問1】情報セキュリティ管理基準（平成28年）に関する記述のうち、適切なものはどれか。','[{"id":"a","text":"ガバナンス基準、管理策基準、マネジメント基準の三つで構成される。"},{"id":"b","text":"JIS Q 27001:2014及びJIS Q 27002:2014との整合性をとっている。"},{"id":"c","text":"情報セキュリティ対策は管理策基準に挙げられた管理策の中から選択することとしている。"},{"id":"d","text":"トップマネジメントはマネジメント基準の事項から自組織に合致するものだけを選択して実施する。"}]','"b"','情報セキュリティ管理基準は関連するISMS規格との整合性を取っている。選択肢の他の記述は基準の構成や適用方法を誤っている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-02','exam-sg','物理セキュリティ','standard','single_choice','【2023年度 IPA公開問題 問2】入室時に認証したIDカードでなければ退室を許可しない、又は退室時に認証したIDカードでなければ再入室を許可しない仕組みはどれか。','[{"id":"a","text":"TPMOR"},{"id":"b","text":"アンチパスバック"},{"id":"c","text":"インターロックゲート"},{"id":"d","text":"パニックオープン"}]','"b"','アンチパスバックは入退室履歴を使い、入室・退室の順序や同じ認証媒体の使い回しを制御する仕組み。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-03','exam-sg','デジタルフォレンジック','standard','single_choice','【2023年度 IPA公開問題 問3】デジタルフォレンジックスの説明はどれか。','[{"id":"a","text":"脅威情報を標準化して記述し、セキュリティ機器に提供する。"},{"id":"b","text":"メール添付の実行ファイルを動作させ、不正な振る舞いを保存前に確認する。"},{"id":"c","text":"インシデント発生時に法的証拠となるデータを収集・保管し、調査分析する。"},{"id":"d","text":"内部ネットワークの通信データを暗号化し盗聴を防ぐ。"}]','"c"','デジタルフォレンジックは、インシデント等に関する電子的証拠を適切に収集・保全・分析する活動。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-04','exam-sg','暗号技術','standard','single_choice','【2023年度 IPA公開問題 問4】暗号方式に関する記述のうち、適切なものはどれか。','[{"id":"a","text":"公開鍵暗号と共通鍵暗号は、ともに大きな合成数の素因数分解が安全性の根拠である。"},{"id":"b","text":"公開鍵暗号はセッションごとに異なる鍵を使うが、共通鍵暗号は一度生成した鍵を必ず使い回す。"},{"id":"c","text":"公開鍵暗号は標準化されているが、共通鍵暗号は一般にベンダー独自仕様である。"},{"id":"d","text":"大量のデータを短時間で暗号化する場合、公開鍵暗号より共通鍵暗号が適している。"}]','"d"','共通鍵暗号は処理が高速で、大量データの暗号化に向く。公開鍵暗号は鍵配送や署名などで重要な役割を持つ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-05','exam-sg','ハッシュ関数','standard','single_choice','【2023年度 IPA公開問題 問5】SHA-256でファイルAとファイルBを計算したところ、64桁の16進数で表すハッシュ値が完全に一致した。適切な説明はどれか。','[{"id":"a","text":"内容を変えず再計算すると、二つのハッシュ値は異なる。"},{"id":"b","text":"ハッシュ値のデータ量は64バイトである。"},{"id":"c","text":"二つを連結したファイルのハッシュ値は128桁になる。"},{"id":"d","text":"ファイルAとBの内容が同一である可能性が高いが、衝突の可能性だけで同一と断定はできない。"}]','"d"','SHA-256は256ビット＝16進数64桁。ハッシュ一致は同一内容を強く示唆するが、理論上衝突はあり得るため数学的な同一証明ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-06','exam-sg','メールセキュリティ','standard','single_choice','【2023年度 IPA公開問題 問6】迷惑メール対策のSPF（Sender Policy Framework）の仕組みはどれか。','[{"id":"a","text":"送信ドメイン管理者が正規の送信メールサーバのIPアドレスをDNSに登録し、受信側が参照して送信元を判定する。"},{"id":"b","text":"送信メールサーバがメッセージに電子署名を付け、受信側が検証する。"},{"id":"c","text":"第三者提供の迷惑メール送信元IPアドレスデータベースを参照する。"},{"id":"d","text":"ファイアウォールが要求・応答パケットを照合してメール通信を制御する。"}]','"a"','SPFはDNSのTXTレコード等で送信元として許可するサーバを公開し、受信側が送信元IPを検証する仕組み。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-07','exam-sg','Webアプリケーションセキュリティ','standard','single_choice','【2023年度 IPA公開問題 問7】Webアプリケーションの脅威と対策の組合せとして、適切なものはどれか。','[{"id":"a","text":"OSコマンドインジェクション対策として、推測困難なセッションIDを使う。"},{"id":"b","text":"SQLインジェクション対策として、DB問い合わせにプレースホルダを使用する。"},{"id":"c","text":"XSS対策として、Webサーバ内ファイルを外部から直接参照できなくする。"},{"id":"d","text":"セッションハイジャック対策として、Webアプリからシェルを起動できなくする。"}]','"b"','プレースホルダを用いたパラメータ化クエリは、入力値をSQL構文として解釈させないためSQLインジェクション対策になる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-08','exam-sg','電子署名','standard','single_choice','【2023年度 IPA公開問題 問8】電子署名法に関する記述のうち、適切なものはどれか。','[{"id":"a","text":"電子署名には電磁的記録ではないものも含まれる。"},{"id":"b","text":"一定の要件を満たす電子署名が行われた電子文書は、真正に成立したものと推定される。"},{"id":"c","text":"電子署名の認証業務は政府運営の認証局に限られる。"},{"id":"d","text":"電子署名は共通鍵暗号技術によるものに限られる。"}]','"b"','電子署名法は、一定の要件を満たす電子署名が行われた電子文書について、真正に成立したものと推定する規定を置く。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-09','exam-sg','インシデント管理','standard','single_choice','【2023年度 IPA公開問題 問9】インシデント管理の監査で、監査報告書に指摘事項として記載すべき状況はどれか。','[{"id":"a","text":"対応手順が作成され、関係者に周知されている。"},{"id":"b","text":"被害を最小化するため、規程に従いデータをバックアップしている。"},{"id":"c","text":"インシデントの種類、発生箇所、影響度に関係なく連絡・報告ルートが共通である。"},{"id":"d","text":"全インシデントの記録を残し、責任者の承認を得ることが定められている。"}]','"c"','インシデントの種類や影響度に応じて適切な連絡・報告ルートを定めるべきで、すべてを一律にする運用は不適切。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-10','exam-sg','Cookie・Web','standard','single_choice','【2023年度 IPA公開問題 問10】HTTPのCookieに関する記述のうち、適切なものはどれか。','[{"id":"a","text":"Cookieに含まれる情報はHTTPヘッダーの一部として送信される。"},{"id":"b","text":"Cookieの情報はWebサーバだけに保存される。"},{"id":"c","text":"CookieはWebブラウザが必ず全て暗号化して送信する。"},{"id":"d","text":"Cookieの有効期限はクライアントだけが設定できる。"}]','"a"','ブラウザはCookieをHTTPリクエストヘッダーに含めて送信する。Cookie自体が自動的に暗号化されるわけではなく、通信にはHTTPS等が必要。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-11','exam-sg','業務プロセス管理','standard','single_choice','【2023年度 IPA公開問題 問11】BPMの説明はどれか。','[{"id":"a","text":"生産、物流、販売、財務、人事などの情報を一元管理し、経営資源の全体最適を実現する。"},{"id":"b","text":"業務プロセスに分析・設計・実行・改善のサイクルを取り入れ、継続的に見直す。"},{"id":"c","text":"顧客データを基に販売から保守、問合せ対応まで顧客関連業務を一貫管理する。"},{"id":"d","text":"部品供給から販売までの情報をリアルタイム交換し、在庫とリードタイムを削減する。"}]','"b"','BPMは業務プロセスを継続的に分析・設計・実行・監視・改善する管理手法。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-12','exam-sg','品質管理','standard','single_choice','【2023年度 IPA公開問題 問12】品質管理において、結果と原因との関連を整理して魚の骨のような図にまとめたものはどれか。','[{"id":"a","text":"管理図"},{"id":"b","text":"特性要因図"},{"id":"c","text":"パレート図"},{"id":"d","text":"ヒストグラム"}]','"b"','特性要因図（魚の骨図）は、結果に影響する原因候補を体系的に整理するための図。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-13','exam-sg','リスクアセスメント','standard','single_choice','【2023年度 IPA公開問題 問13】情報資産の重要度は機密性・完全性・可用性の評価値の最大値とし、リスク値＝重要度×脅威評価値×脆弱性評価値、しきい値は5とする。保有以外のリスク対応が必要な資産の組合せはどれか。','[{"id":"a","text":"(一)、(二)"},{"id":"b","text":"(一)、(二)、(三)"},{"id":"c","text":"(一)、(二)、(四)"},{"id":"d","text":"(一)、(三)"},{"id":"e","text":"(一)、(三)、(四)"},{"id":"f","text":"(一)、(四)"},{"id":"g","text":"(二)、(三)"},{"id":"h","text":"(二)、(三)、(四)"},{"id":"i","text":"(二)、(四)"},{"id":"j","text":"(三)、(四)"}]','"d"','各資産の最大CIA値を重要度としてリスク値を計算し、5を超える資産を選ぶ。公式解答はエ（(一)、(三)）。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-14','exam-sg','バックアップ','standard','single_choice','【2023年度 IPA公開問題 問14】毎週土曜に顧客情報を磁気テープへバックアップし、2世代をサーバ隣のキャビネットに保管している。バックアップ対象フォルダの設定ミスによる復旧不能リスクを低減するために有効な対策を二つ選んだ組合せはどれか。','[{"id":"a","text":"毎日バックアップし7世代保存する／バックアップ媒体を外付けHDDに変える"},{"id":"b","text":"毎日バックアップし7世代保存する／2名で設定する"},{"id":"c","text":"毎日バックアップし7世代保存する／二組取得し一組を遠隔地保管する"},{"id":"d","text":"毎日バックアップし7世代保存する／バックアップ後にファイルリストを比較する"},{"id":"e","text":"バックアップ後にファイルリストを比較する／2名で設定する"},{"id":"f","text":"バックアップ後にファイルリストを比較する／媒体を外付けHDDに変える"},{"id":"g","text":"バックアップ後にファイルリストを比較する／二組取得し一組を遠隔地保管する"},{"id":"h","text":"2名で設定する／媒体を外付けHDDに変える"},{"id":"i","text":"2名で設定する／二組取得し一組を遠隔地保管する"},{"id":"j","text":"媒体を外付けHDDに変える／二組取得し一組を遠隔地保管する"}]','"e"','対象フォルダの設定ミスを検知するには、バックアップ後に対象ファイル一覧と保存済み一覧を照合すること、設定を二人で確認することが有効。公式解答はオ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja'),
('sg-official-2023-15','exam-sg','メールセキュリティ','standard','single_choice','【2023年度 IPA公開問題 問15】不審なメール添付を開いた後、認証アプリに身に覚えのないログイン承認要求が届いた。マルウェア対策ソフトの定義ファイルは毎日16時更新で、当該マルウェアは当日9時公開の定義で検出可能だった。再発防止策として適切なものはどれか。','[{"id":"a","text":"PC起動時に必ずVPN接続する。"},{"id":"b","text":"初めての送信者の添付ファイルは全て開かず削除する。"},{"id":"c","text":"マルウェア定義ファイルを8時にも更新する。"},{"id":"d","text":"定義ファイルを10分ごとに更新する。"},{"id":"e","text":"添付ファイルをPCに保存し、対策ソフトでスキャンしてから開く。"}]','"c"','最新定義が9時に公開され、16時更新では検出まで遅れが生じた。朝の更新を追加することで新しい脅威への検出遅延を減らせる。公式解答はウ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/t6hhco0000003zx0-att/2023r05_sg_qs.pdf','ja');
